19	/** Claim figures and due-totals, as the screen shows them. */
20	public final class Dues {
21	    private Dues() {
22	    }
23	
24	    /** A claim's figure: the due fixed when it was settled, else the one its last statement bound it to, n/a
25	     *  included (not while it is PENDING: then it is live), else
26	     *  live: its amount times its person's rate in force on its date for their grade then, divided by 100, rounded to two
27	     *  decimals as the claim rounds (see Rounding), and at least the sheet's floor in force on its date; null (n/a) when no rate applies. */
28	    public static BigDecimal figure(Claim claim, Grades grades, RateRepository rates, DatedAmount floor,
29	            Rounding rounding) {
30	        if (claim.settledDue() != null) {
31	            return claim.settledDue();
32	        }
33	        if (claim.stated() && claim.status() != ClaimStatus.PENDING) {
34	            return claim.statedDue();
35	        }
36	        return live(claim, grades, rates, floor, rounding);
37	    }
38	
39	    /** A claim's due as its row shows it: the due fixed when it was settled, else its figure (bound or live) with
40	     *  the late charge on it added on top; null (n/a) when it has no figure. */
41	    public static BigDecimal shown(Claim claim, Grades grades, RateRepository rates, DatedAmount floor,
42	            LateCharge late) {
43	        if (claim.settledDue() != null) {
44	            return claim.settledDue();
45	        }
46	        BigDecimal figure = figure(claim, grades, rates, floor, late.rounding());
47	        return figure != null ? figure.add(late.on(claim, figure)) : null;
48	    }
49	
50	    /** A claim's live due: its amount times its person's rate in force on its date for their grade then, divided by 100, rounded
51	     *  to two decimals as the claim rounds (see Rounding), raised to the floor in force on its date when below it (a correction, a negative amount, has no floor); null (n/a) when no rate applies. */
52	    public static BigDecimal live(Claim claim, Grades grades, RateRepository rates, DatedAmount floor,
53	            Rounding rounding) {
54	        return rates.on(claim.sheetId(), grades.on(claim.date()), claim.date())
55	                .map(r -> claim.amount().multiply(r.pct()).divide(BigDecimal.valueOf(100), 2, rounding.of(claim)))
56	                .map(due -> claim.amount().signum() < 0 ? due : due.max(floor.on(claim.date())))
57	                .orElse(null);
58	    }
59	
60	    /** Whether a claim counts toward its person's figures and every live total: an OPEN, PENDING or SETTLED one,
61	     *  except an OPEN one dated within one of its person's holds and not bound by a statement, and one deferred on the
62	     *  sheet's today (see Claim.deferredOn). */
63	    public static boolean counts(Claim claim, Holds holds, LocalDate today) {
64	        return claim.status().counts() && !claim.deferredOn(today)
65	                && !(claim.status() == ClaimStatus.OPEN && !claim.stated() && holds.covers(claim.date()));
66	    }
67	
68	    /** A person's due-total: the dues (as shown) of their claims that count added up, skipping n/a; null (n/a) when
69	     *  their grade today has no rate today, unless a claim that counts has a figure (settled, stated, or live at
70	     *  the grade in force on its date). */
71	    public static BigDecimal total(String sheetId, List<Claim> claims, Grades grades, Holds holds, LocalDate today,
72	            RateRepository rates, DatedAmount floor, LateCharge late) {
73	        List<Claim> counted = claims.stream().filter(c -> counts(c, holds, today)).toList();
74	        List<BigDecimal> figures = counted.stream().map(c -> shown(c, grades, rates, floor, late))
75	                .filter(f -> f != null).toList();
76	        if (figures.isEmpty() && rates.on(sheetId, grades.on(today), today).isEmpty()) {
77	            return null;
78	        }
79	        return figures.stream().reduce(new BigDecimal("0.00"), BigDecimal::add);
80	    }
81	
82	    /** A due-total at most the sheet's cap (null: none); n/a (null) is not capped. */
83	    public static BigDecimal capped(BigDecimal total, BigDecimal cap) {
84	        return total != null && cap != null ? total.min(cap) : total;
85	    }
