91	/** The sheet's late charge as it is today: its late percent by date (a claim gains the one in force on its date; a claim is overdue past its own due-by, fixed when
92	 *  it was created) and its today (null: none, so nothing is overdue). */
93	public record LateCharge(DatedAmount pct, LocalDate today, Rounding rounding) {
94	
95	    /** The sheet's late charge as it is now. */
96	    public static LateCharge of(String sheetId, SettingRepository settings, SheetRepository sheets,
97	            ClaimRepository claims) {
98	        return new LateCharge(settings.latePct(sheetId), sheets.today(sheetId),
99	                Rounding.of(sheetId, settings, sheets, claims));
100	    }
101	
102	    /** No late charge at all. */
103	    public static LateCharge none() {
104	        return new LateCharge(DatedAmount.always(BigDecimal.ZERO), null, Rounding.none());
105	    }
106	
107	    /** Whether a claim is overdue: it is OPEN or PENDING, not deferred on today, and its due-by is before today. */
108	    public boolean overdue(Claim claim) {
109	        return claim.status().unsettled() && today != null && !claim.deferredOn(today)
110	                && claim.dueBy().isBefore(today);
111	    }
112	
113	    /** The charge on a claim whose figure is `figure`: the late percent in force on its date, of the figure, for every full 30 days it
114	     *  is overdue, rounded to two decimals as the claim rounds (see Rounding); 0.00 when it is not overdue, or it is a correction (a negative amount). */
115	    public BigDecimal on(Claim claim, BigDecimal figure) {
116	        BigDecimal pct = this.pct.on(claim.date());
117	        if (!overdue(claim) || pct.signum() == 0 || claim.amount().signum() < 0) {
118	            return new BigDecimal("0.00");
119	        }
120	        long periods = ChronoUnit.DAYS.between(claim.dueBy(), today) / 30;
121	        return figure.multiply(pct).multiply(BigDecimal.valueOf(periods))
122	                .divide(BigDecimal.valueOf(100), 2, rounding.of(claim));
123	    }
124	}
