164	/** Take the person's statement: record their due-total now (late charges included, at most the sheet's cap) and the sheet's today, bind
165	 *  each of their claims that counts to the figure under it now (never its late charge, which keeps following the
166	 *  sheet's today), and unbind the rest (their due is live again; a claim deferred on today is left unbound). A settled claim's
167	 *  fixed due is left as it is. */
168	public class SaveStatement {
169	    public void save(@Val Person loaded, PersonRepository people, ClaimRepository claims, RateRepository rates,
170	            SheetRepository sheets, SettingRepository settings, Out<Statement> statement, Out<PersonResponse> saved) {
171	        people.lock(loaded);
172	        Person person = people.find(loaded.sheetId(), loaded.id());
173	        var today = sheets.today(person.sheetId());
174	        var floor = settings.floor(person.sheetId());
175	        List<Claim> theirs = claims.listForPerson(person.sheetId(), person.id());
176	        LateCharge late = LateCharge.of(person.sheetId(), settings, sheets, claims);
177	        BigDecimal total = Dues.capped(Dues.total(person.sheetId(), theirs, person.grades(), person.holds(), today,
178	                rates, floor, late), settings.cap(person.sheetId()));
179	        int counted = 0;
180	        for (Claim c : theirs) {
181	            if (Dues.counts(c, person.holds(), today)) {
182	                counted++;
183	                claims.state(c, true, Dues.figure(c, person.grades(), rates, floor, late.rounding()));
184	            } else if (c.stated()) {
185	                claims.state(c, false, null);
186	            }
187	        }
188	        people.stated(person, total, today);
189	        statement.set(new Statement(person.sheetId(), person.name(), total, counted));
190	        saved.set(PersonResponse.from(people.find(person.sheetId(), person.id())));
191	    }
192	}
