343	package net.officefloor.hq.app.rollup;
344	
345	
346	/** Takes the sheet's figures, and records in the audit file how they moved over a change: a ROLLUP line per
347	 *  person whose figures (claimed, due-total, overdue-total) changed (a person new to the sheet counting as changed), in the order they were added,
348	 *  then a TOTALS line when the sheet's totals changed. A change that moves no figure records nothing. */
349	@Service
350	public class Rollups {
351	
352	    private final PersonRepository people;
353	    private final ClaimRepository claims;
354	    private final RateRepository rates;
355	    private final SheetRepository sheets;
356	    private final SettingRepository settings;
357	    private final Audit audit;
358	
359	    public Rollups(PersonRepository people, ClaimRepository claims, RateRepository rates, SheetRepository sheets,
360	            SettingRepository settings, Audit audit) {
361	        this.people = people;
362	        this.claims = claims;
363	        this.rates = rates;
364	        this.sheets = sheets;
365	        this.settings = settings;
366	        this.audit = audit;
367	    }
368	
369	    /** The sheet's figures as they are now. */
370	    public Rollup take(String sheetId) {
371	        var today = sheets.today(sheetId);
372	        var floor = settings.floor(sheetId);
373	        BigDecimal cap = settings.cap(sheetId);
374	        LateCharge late = LateCharge.of(sheetId, settings, sheets, claims);
375	        List<Claim> all = claims.list(sheetId);
376	        Map<Long, Rollup.Figures> figures = new LinkedHashMap<>();
377	        BigDecimal claimedTotal = new BigDecimal("0.00");
378	        BigDecimal dueTotal = new BigDecimal("0.00");
379	        BigDecimal overdueTotal = new BigDecimal("0.00");
380	        for (Person p : people.list(sheetId)) {
381	            List<Claim> theirs = all.stream().filter(c -> c.personId() == p.id()).toList();
382	            BigDecimal claimed = theirs.stream().filter(c -> Dues.counts(c, p.holds(), today)).map(Claim::amount)
383	                    .reduce(new BigDecimal("0.00"), BigDecimal::add);
384	            BigDecimal due = Dues.capped(
385	                    Dues.total(sheetId, theirs, p.grades(), p.holds(), today, rates, floor, late), cap);
386	            // overdue-total: the dues (as shown, late charge included) of their overdue claims that count, skipping n/a
387	            BigDecimal overdue = theirs.stream().filter(c -> Dues.counts(c, p.holds(), today) && late.overdue(c))
388	                    .map(c -> Dues.shown(c, p.grades(), rates, floor, late)).filter(Objects::nonNull)
389	                    .reduce(new BigDecimal("0.00"), BigDecimal::add);
390	            claimedTotal = claimedTotal.add(claimed);
391	            overdueTotal = overdueTotal.add(overdue);
392	            if (due != null) {
393	                dueTotal = dueTotal.add(due);
394	            }
395	            figures.put(p.id(), new Rollup.Figures(p.name(), shown(claimed), due != null ? shown(due) : "n/a",
396	                    shown(overdue)));
397	        }
398	        return new Rollup(figures, shown(claimedTotal), shown(dueTotal), shown(overdueTotal));
399	    }
400	
401	    /** Record how the sheet's figures moved since `before`, as a change made by `user`. */
402	    public void record(String sheetId, String user, Rollup before) {
403	        Rollup after = take(sheetId);
404	        for (var e : after.people().entrySet()) {
405	            Rollup.Figures was = before.people().get(e.getKey());
406	            Rollup.Figures now = e.getValue();
407	            if (was == null || !Objects.equals(was.claimed(), now.claimed())
408	                    || !Objects.equals(was.dueTotal(), now.dueTotal())
409	                    || !Objects.equals(was.overdueTotal(), now.overdueTotal())) {
410	                audit.record("ROLLUP sheet=" + sheetId + " by=" + user + " person=" + now.name()
411	                        + " claimed=" + now.claimed() + " due-total=" + now.dueTotal() + " overdue-total=" + now.overdueTotal());
412	            }
413	        }
414	        if (!before.claimedTotal().equals(after.claimedTotal()) || !before.dueTotal().equals(after.dueTotal())
415	                || !before.overdueTotal().equals(after.overdueTotal())) {
416	            audit.record("TOTALS sheet=" + sheetId + " by=" + user + " claimed-total=" + after.claimedTotal()
417	                    + " due-total=" + after.dueTotal() + " overdue-total=" + after.overdueTotal());
418	        }
419	    }
420	
421	    private static String shown(BigDecimal value) {
422	        return value.setScale(2, RoundingMode.HALF_EVEN).toPlainString();
423	    }
424	}
