652	 *  blank (the sheet's today) or a date yyyy-mm-dd, and a period numbering from (when given) that is blank (off) or a date yyyy-mm-dd, and grades' own terms (when given)
653	 *  only for grades A, B or C, and a cap (when given) that is blank (none) or an amount 0.00 or more with up to two decimals, each blank (none: the sheet's terms) or a whole number of days, and from-dates (when given) only for the dated settings, each blank (the sheet's
654	 *  today) or a date yyyy-mm-dd. */
655	public class ValidateSettings {
656	    /** The grades that may have terms of their own. */
657	    static final List<String> GRADES = List.of("A", "B", "C");
658	
659	    private static final String PERCENT = "\\d{1,3}(\\.\\d{1,2})?";
660	    private static final String AMOUNT = "\\d{1,12}(\\.\\d{1,2})?";
661	
662	    public void validate(@RequestBody SettingsRequest request, Out<SettingsInput> body) throws InvalidSettingException {
663	        if (request == null || request.user() == null || request.user().isBlank()) {
664	            throw new InvalidSettingException("Sign in before changing settings.");
665	        }
666	        String limit = request.clerkLimit() == null ? null : request.clerkLimit().trim();
667	        if (limit != null && !limit.isEmpty() && !limit.matches(AMOUNT)) {
668	            throw new InvalidSettingException("The clerk limit must be an amount, 0.00 or more, with up to two decimals, or blank for no limit.");
669	        }
670	        String floor = request.floor() == null ? null : request.floor().trim();
671	        if (floor != null && !floor.matches(AMOUNT)) {
672	            throw new InvalidSettingException("The floor must be an amount, 0.00 or more, with up to two decimals.");
673	        }
674	        String terms = request.terms() == null ? null : request.terms().trim();
675	        if (terms != null && !terms.matches("\\d{1,4}")) {
676	            throw new InvalidSettingException("The terms must be a whole number of days, 0 or more.");
677	        }
678	        String latePct = request.latePct() == null ? null : request.latePct().trim();
679	        if (latePct != null && !latePct.matches(PERCENT)) {
680	            throw new InvalidSettingException("The late percent must be a percent, 0.00 or more, with up to two decimals.");
681	        }
682	        String policy = request.policyDate() == null ? null : request.policyDate().trim();
683	        LocalDate policyDate = null;
684	        if (policy != null && !policy.isEmpty()) {
685	            try {
686	                policyDate = LocalDate.parse(policy);
687	            } catch (DateTimeParseException e) {
688	                throw new InvalidSettingException("The policy date must be a date, yyyy-mm-dd, or blank for the sheet's today.");
689	            }
690	        }
691	        String numbering = request.periodNumberingFrom() == null ? null : request.periodNumberingFrom().trim();
692	        LocalDate numberingFrom = null;
693	        if (numbering != null && !numbering.isEmpty()) {
694	            try {
695	                numberingFrom = LocalDate.parse(numbering);
696	            } catch (DateTimeParseException e) {
697	                throw new InvalidSettingException("The period numbering from must be a date, yyyy-mm-dd, or blank for off.");
698	            }
699	        }
700	        String cap = request.cap() == null ? null : request.cap().trim();
701	        if (cap != null && !cap.isEmpty() && !cap.matches(AMOUNT)) {
702	            throw new InvalidSettingException("The cap must be an amount, 0.00 or more, with up to two decimals, or blank for none.");
703	        }
704	        Map<String, Integer> gradeTerms = new LinkedHashMap<>();
705	        if (request.gradeTerms() != null) {
706	            for (String grade : request.gradeTerms().keySet()) {
707	                if (!GRADES.contains(grade)) {
