64	/** Open each selected claim that can be opened, in list order (people in the order they were added, newest
65	 *  claim first within a person), giving each the sheet's next number. Each is opened as a single open would be,
66	 *  with its OPEN line in its status log, its CLAIM_OPENED line and then how the sheet's figures moved over it. A selected claim that cannot be
67	 *  opened (not on the sheet, not a DRAFT, or dated in a closed period) is left as it is and counted as refused. */
68	public class BulkOpenClaims {
69	    public void open(@PathVariable("sheetId") String sheetId, @Val BulkOpenInput input, ClaimRepository claims, ClaimLogRepository log,
70	            PersonRepository people, PeriodRepository periods, Rollups rollups, Audit audit,
71	            Out<BulkOpenResponse> result) {
72	        String sheet = sheetId.trim();
73	        periods.lockSheet(sheet);
74	        int opened = 0;
75	        for (Person person : people.list(sheet)) {
76	            List<Claim> theirs = claims.listForPerson(sheet, person.id()).stream()
77	                    .filter(c -> input.claimIds().contains(c.id())).toList();
78	            for (Claim claim : theirs) {
79	                if (claim.status().canBecome(ClaimStatus.OPEN) && periods.closedOn(sheet, claim.date()) == null) {
80	                    Rollup before = rollups.take(sheet);
81	                    String number = claims.nextNumber(sheet, claim.date());
82	                    claims.changeStatus(claim, ClaimStatus.OPEN, number, claim.settledDue(), input.user());
83	                    log.record(claim, input.user());
84	                    audit.record("CLAIM_OPENED sheet=" + sheet + " by=" + input.user() + " person=" + person.name()
85	                            + " amount=" + claim.amount().toPlainString() + " date=" + claim.date() + " number=" + number);
86	                    rollups.record(sheet, input.user(), before);
87	                    opened++;
88	                }
89	            }
90	        }
91	        result.set(new BulkOpenResponse(opened, input.claimIds().size() - opened));
92	    }
93	}
