108	 *  claim first within a person), by exactly the rules of settling one claim: each that goes through (SETTLED, or
109	 *  PENDING for a clerk's settle above the clerk limit) gets its status log line, its CLAIM_SETTLED or CLAIM_PENDING
110	 *  line and then how the sheet's figures moved over it. A selected claim that cannot be settled (not on the sheet,
111	 *  not allowed from its status or by this user, or dated in a closed period) is left as it is and counted as
112	 *  refused. */
113	public class BulkSettleClaims {
114	    public void settle(@PathVariable("sheetId") String sheetId, @Val BulkSettleInput input, ClaimRepository claims,
115	            ClaimLogRepository log, PersonRepository people, PeriodRepository periods, RateRepository rates,
116	            RoleRepository roles, SettingRepository settings, SheetRepository sheets, Rollups rollups, Audit audit,
117	            Out<BulkSettleResponse> result) {
118	        String sheet = sheetId.trim();
119	        periods.lockSheet(sheet);
120	        ClaimStatusInput settle = new ClaimStatusInput(input.user(), "settle", ClaimStatus.SETTLED, null);
121	        int settled = 0;
122	        for (Person person : people.list(sheet)) {
123	            List<Claim> theirs = claims.listForPerson(sheet, person.id()).stream()
124	                    .filter(c -> input.claimIds().contains(c.id())).toList();
125	            for (Claim claim : theirs) {
126	                if (periods.closedOn(sheet, claim.date()) != null) {
127	                    continue;
128	                }
129	                Rollup before = rollups.take(sheet);
130	                ClaimResponse saved;
131	                try {
132	                    saved = ClaimStatusChange.save(settle, claim, claims, people, rates, roles, settings, sheets, log);
