324	                rs -> rs.next() ? rs.getBoolean(1) : false, sheetId);
325	        if (!Boolean.TRUE.equals(byPeriod)) {
326	            jdbc.update("UPDATE sheet SET last_claim_number = last_claim_number + 1 WHERE id = ?", sheetId);
327	            return String.valueOf(jdbc.queryForObject("SELECT last_claim_number FROM sheet WHERE id = ?",
328	                    Integer.class, sheetId));
329	        }
330	        String[] period = jdbc.query(
331	                "SELECT name, name_key FROM period WHERE sheet_id = ? AND from_date <= ? AND to_date >= ? ORDER BY from_date",
332	                rs -> rs.next() ? new String[] { rs.getString(1), rs.getString(2) } : null, sheetId, date, date);
