373	/** The rules of a claim's status change and its audit line, shared by a single change ({@link SaveClaimStatus},
374	 *  {@link AuditClaimStatus}) and a bulk settle ({@link BulkSettleClaims}). */
375	final class ClaimStatusChange {
376	    private ClaimStatusChange() {
377	    }
378	    /** Move the claim to its new status as {@link SaveClaimStatus} describes, adding it to its status log: the claim
379	     *  as stored now; throws (having written nothing) when the change is not allowed. */
380	    static ClaimResponse save(ClaimStatusInput input, Claim loaded, ClaimRepository repository,
381	            PersonRepository people, RateRepository rates, RoleRepository roles, SettingRepository settings,
382	            SheetRepository sheets, ClaimLogRepository log)
383	            throws ClaimStatusNotAllowedException {
384	        ClaimStatus to = input.to();
385	        boolean review = input.action().equals("approve") || input.action().equals("reject");
386	        if (review) {
387	            if (loaded.status() != ClaimStatus.PENDING) {
388	                throw new ClaimStatusNotAllowedException("Only a PENDING claim can be " + input.action()
389	                        + "d; this one is " + loaded.status() + ".");
390	            }
391	            if (!Role.STEWARD.equals(roles.of(loaded.sheetId(), input.user()))) {
392	                throw new ClaimStatusNotAllowedException("Only a steward can " + input.action() + " a PENDING claim.");
393	            }
394	            if (input.action().equals("approve") && input.user().equals(loaded.openedBy())) {
395	                throw new ClaimStatusNotAllowedException("The user who opened a claim cannot approve it.");
396	            }
397	        } else if (input.action().equals("resettle")) {
398	            if (loaded.status() != ClaimStatus.SETTLED) {
399	                throw new ClaimStatusNotAllowedException("Only a SETTLED claim can be re-settled; this one is "
400	                        + loaded.status() + ".");
401	            }
402	            if (!Role.STEWARD.equals(roles.of(loaded.sheetId(), input.user()))) {
403	                throw new ClaimStatusNotAllowedException("Only a steward can re-settle a claim.");
404	            }
405	        } else if (!loaded.status().canBecome(to)) {
406	            throw new ClaimStatusNotAllowedException(loaded.status(), to);
407	        }
408	        if (input.action().equals("settle") && loaded.deferredOn(sheets.today(loaded.sheetId()))) {
409	            throw new ClaimStatusNotAllowedException("This claim is deferred until " + loaded.deferredUntil()
410	                    + "; it cannot be settled before then.");
411	        }
412	        if (input.action().equals("settle") && input.user().equals(loaded.openedBy())) {
413	            throw new ClaimStatusNotAllowedException("The user who opened a claim cannot settle it.");
414	        }
415	        if (input.action().equals("settle") && Role.CLERK.equals(roles.of(loaded.sheetId(), input.user()))) {
416	            BigDecimal limit = settings.clerkLimit(loaded.sheetId());
417	            BigDecimal due = dueNow(loaded, repository, people, rates, settings, sheets);
418	            if (limit != null && due != null && due.compareTo(limit) > 0) {
419	                to = ClaimStatus.PENDING;
420	            }
421	        }
422	        boolean opening = input.action().equals("open");
