575	/** Check every pasted line against the sheet first, as the claim form would for its person: the name must be on
576	 *  the sheet (compared as names are), the claim not dated (a blank date being the sheet's today) after the person's
577	 *  retirement date nor inside a closed period. Any failure refuses the whole paste, naming the line, and nothing
578	 *  is written. Otherwise each line is added in order as a DRAFT claim, just as the claim form adds one: its
579	 *  CLAIM_ADDED line and then how the sheet's figures moved over it. */
580	public class PasteClaims {
581	    public void paste(@PathVariable("sheetId") String sheetId, @Val PasteInput input, PersonRepository people,
582	            SheetRepository sheets, SettingRepository settings, PeriodRepository periods, ClaimRepository claims,
583	            ClaimLogRepository log, Rollups rollups, Audit audit, Out<PasteResponse> result)
584	            throws InvalidClaimException {
585	        String sheet = sheetId.trim();
586	        periods.lockSheet(sheet);
587	        List<Person> owners = new ArrayList<>();
588	        for (PasteLine line : input.lines()) {
589	            Person person = people.findByName(sheet, line.name());
590	            if (person == null) {
591	                throw new InvalidClaimException("Line " + line.number() + ": " + line.name() + " is not on the sheet.");
592	            }
593	            var date = line.claim().date() != null ? line.claim().date() : sheets.today(sheet);
594	            try {
595	                RetiredPersonException.refuse(person, date);
596	            } catch (RetiredPersonException e) {
597	                throw new InvalidClaimException("Line " + line.number() + ": " + e.getMessage());
598	            }
599	            Period closed = periods.closedOn(sheet, date);
600	            if (closed != null) {
601	                throw new InvalidClaimException("Line " + line.number() + ": " + new ClosedPeriodException(closed).getMessage());
602	            }
603	            owners.add(person);
604	        }
605	        for (int i = 0; i < owners.size(); i++) {
606	            ClaimInput claim = input.lines().get(i).claim();
607	            Person person = owners.get(i);
608	            Rollup before = rollups.take(sheet);
609	            Claim added = SaveNewClaim.insert(claim, person, sheets, settings, claims, log);
610	            AuditClaimAdded.record(claim, person, added, audit);
611	            rollups.record(sheet, input.user(), before);
612	        }
613	        result.set(new PasteResponse(owners.size()));
614	    }
615	}
