429	/** Close the named period, fixing its due-total, and each person's on the sheet, as they are now: the figures (as shown on their rows) of the claims
430	 *  that count (an OPEN one dated within a hold of its person, not bound by a statement, does not) whose date falls in it, skipping n/a. Refused when there is no such period, or it is already
431	 *  closed. */
432	public class ClosePeriod {
433	    public void close(@PathVariable("sheetId") String sheetId, @PathVariable("periodName") String periodName,
434	            PeriodRepository periods, ClaimRepository claims, PersonRepository people, RateRepository rates,
435	            SettingRepository settings, SheetRepository sheets,
436	            Out<Period> closed) throws InvalidPeriodException {
437	        String id = sheetId.trim();
438	        periods.lockSheet(id);
439	        Period period = periods.find(id, periodName);
440	        if (period == null) {
441	            throw new InvalidPeriodException("There is no period " + periodName.trim() + " on this sheet.");
442	        }
443	        if (period.closed()) {
444	            throw new InvalidPeriodException("The period " + period.name() + " is already closed.");
445	        }
446	        Map<Long, Person> byId = people.list(id).stream().collect(Collectors.toMap(Person::id, Function.identity()));
447	        var floor = settings.floor(id);
448	        LateCharge late = LateCharge.of(id, settings, sheets, claims);
449	        Map<Long, BigDecimal> personTotals = new LinkedHashMap<>();
450	        for (Long personId : byId.keySet()) {
451	            personTotals.put(personId, new BigDecimal("0.00"));
452	        }
453	        BigDecimal total = new BigDecimal("0.00");
454	        for (Claim c : claims.list(id)) {
455	            Person person = byId.get(c.personId());
456	            if (!Dues.counts(c, person != null ? person.holds() : Holds.NONE, late.today()) || !period.contains(c.date())) {
457	                continue;
458	            }
459	            BigDecimal figure = Dues.shown(c, person != null ? person.grades() : Grades.NONE, rates, floor, late);
460	            if (figure != null) {
461	                total = total.add(figure);
462	                if (person != null) {
463	                    personTotals.merge(person.id(), figure, BigDecimal::add);
464	                }
465	            }
466	        }
467	        if (!periods.close(period, total, personTotals)) {
468	            throw new InvalidPeriodException("The period " + period.name() + " is already closed.");
469	        }
470	        closed.set(new Period(period.sheetId(), period.name(), period.from(), period.to(), true, total));
471	    }
472	}
