497	@Repository
498	public class PeriodRepository {
499	    private static final RowMapper<Period> ROW = (rs, i) -> new Period(rs.getString("sheet_id"),
500	            rs.getString("name"), rs.getObject("from_date", LocalDate.class), rs.getObject("to_date", LocalDate.class),
501	            rs.getBoolean("closed"), rs.getBigDecimal("closed_total"));
502	    private final JdbcTemplate jdbc;
503	    public PeriodRepository(JdbcTemplate jdbc) {
504	        this.jdbc = jdbc;
505	    }
506	    public List<Period> list(String sheetId) {
507	        return jdbc.query("SELECT * FROM period WHERE sheet_id = ? ORDER BY from_date", ROW, sheetId);
508	    }
509	    /** Lock the sheet's row until the transaction ends, so concurrent period adds are checked one after the other. */
510	    public void lockSheet(String sheetId) {
511	        jdbc.query("SELECT id FROM sheet WHERE id = ? FOR UPDATE", rs -> null, sheetId);
512	    }
513	    public Period insert(String sheetId, String name, LocalDate from, LocalDate to) {
514	        jdbc.update("INSERT INTO period (sheet_id, name, from_date, to_date) VALUES (?, ?, ?, ?)",
515	                sheetId, name, Date.valueOf(from), Date.valueOf(to));
516	        return new Period(sheetId, name, from, to, false, null);
517	    }
518	    /** The period on the sheet with this name (without regard to case or surrounding spaces), or null. */
519	    public Period find(String sheetId, String name) {
520	        return jdbc.query("SELECT * FROM period WHERE sheet_id = ? AND name_key = LOWER(TRIM(?))", ROW, sheetId, name)
521	                .stream().findFirst().orElse(null);
522	    }
523	    /** The closed period on the sheet whose dates contain the date, or null when none does. */
524	    public Period closedOn(String sheetId, LocalDate date) {
525	        return list(sheetId).stream().filter(p -> p.closed() && p.contains(date)).findFirst().orElse(null);
526	    }
527	    /** Close the period, fixing its due-total and each person's (by person id): false when it was already closed,
528	     *  and nothing is written. */
529	    public boolean close(Period period, BigDecimal total, Map<Long, BigDecimal> personTotals) {
530	        if (jdbc.update("UPDATE period SET closed = TRUE, closed_total = ? WHERE sheet_id = ? AND name = ? AND NOT closed",
531	                total, period.sheetId(), period.name()) != 1) {
532	            return false;
533	        }
534	        personTotals.forEach((personId, personTotal) -> jdbc.update(
535	                "INSERT INTO period_person_total (sheet_id, period_name, person_id, total) VALUES (?, ?, ?, ?)",
536	                period.sheetId(), period.name(), personId, personTotal));
537	        return true;
538	    }
539	    /** The people's due-totals fixed in the sheet's closed periods: by period name, then by person id. */
540	    public Map<String, Map<Long, BigDecimal>> personTotals(String sheetId) {
541	        Map<String, Map<Long, BigDecimal>> totals = new HashMap<>();
542	        jdbc.query("SELECT period_name, person_id, total FROM period_person_total WHERE sheet_id = ?", rs -> {
543	            totals.computeIfAbsent(rs.getString("period_name"), k -> new HashMap<>())
544	                    .put(rs.getLong("person_id"), rs.getBigDecimal("total"));
545	        }, sheetId);
546	        return totals;
547	    }
548	    /** Reopen the period, dropping its fixed due-totals: false when it was not closed, and nothing is written. */
549	    public boolean reopen(Period period) {
550	        if (jdbc.update("UPDATE period SET closed = FALSE, closed_total = NULL WHERE sheet_id = ? AND name = ? AND closed",
551	                period.sheetId(), period.name()) != 1) {
552	            return false;
